using System;using System.IO;
class UpdateTests {
 static void Assert(bool x){if(!x)throw new Exception("Assertion failed");}
 static void Reject(Action a){try{a();}catch(Exception){return;}throw new Exception("Expected refusal");}
 static int Main(){Assert(UpdateService.Compare("v0.4.0-test10","0.4.0-test9")>0);Assert(UpdateService.Compare("0.4.0","0.4.0-test99")>0);Assert(UpdateService.Compare("0.5.0-test1","0.4.0")>0);Reject(()=>UpdateService.Compare("latest","0.4.0"));string json="[{\"tag_name\":\"v0.4.0-test12\",\"prerelease\":true},{\"tag_name\":\"v0.4.0-test99\",\"draft\":true},{\"tag_name\":\"v0.4.0\"},{\"tag_name\":\"junk\"}]";Assert(UpdateService.Select(json,true,"0.4.0-test11").tag_name=="v0.4.0");Assert(UpdateService.Select(json,false,"0.4.0-test11").tag_name=="v0.4.0");Assert(UpdateService.Select("[]",true,"0.4.0-test11")==null);Assert(UpdateService.Select("[{\"tag_name\":\"v0.4.1-test1\",\"prerelease\":true}]",false,"0.4.0")==null);Reject(()=>UpdateService.Select("broken",true,"0.4.0"));var r=new UpdateRelease{tag_name="v0.4.0-test12",assets=new[]{new UpdateAsset{name="LegacySteamFixer-v0.4.0-test12-github-source.zip"}}};Reject(()=>UpdateService.Package(r));r.assets=new[]{new UpdateAsset{name="LegacySteamFixer-v0.4.0-test12.zip",browser_download_url="https://github.com/yuyu107/LegacySteamFixer/releases/download/v0.4.0-test12/package.zip"}};Assert(UpdateService.Package(r)!=null);r.assets[0].browser_download_url="https://example.com/package.zip";Reject(()=>UpdateService.Package(r));string hash=new string('a',64);Assert(UpdateService.HashText(hash+"  correct.zip","correct.zip")==hash);Reject(()=>UpdateService.HashText(hash+"  other.zip","correct.zip"));string p=Path.GetTempFileName();try{File.WriteAllText(p,"payload");UpdateService.Verify(p,Core.Hash(p));Reject(()=>UpdateService.Verify(p,hash));Assert(File.ReadAllText(p)=="payload");}finally{File.Delete(p);}Console.WriteLine("PASS: numeric preview versions, stable/preview filtering, drafts, unknown tags, empty/malformed releases, runtime asset selection, asset URL refusal, checksum filename, hash mismatch. No live GitHub download.");return 0;}
}
